from decimal import Decimal, ROUND_HALF_UP


_STAGE_VALUES = {
    "P": ("prospecting", 10),
    "Q": ("qualified", 25),
    "N": ("negotiation", 60),
    "W": ("closed_won", 100),
    "L": ("closed_lost", 0),
}


def _value(row: dict, key: str) -> str:
    value = row.get(key, "")
    return "" if value is None else value


def _decimal_or_zero(value: str) -> Decimal:
    if value == "" or str(value).strip() == "":
        return Decimal(0)
    return Decimal(str(value))


def _date_or_none(value: str) -> str | None:
    if value == "" or value == "00000000":
        return None
    return datetime.strptime(value, "%Y%m%d").date().isoformat()


def convert_opportunity(row: dict) -> dict | None:
    if _value(row, "DEL_FLG") == "Y":
        return None

    stat_code = _value(row, "STAT_CD")
    stage_entry = _STAGE_VALUES.get(stat_code)
    stage = stage_entry[0] if stage_entry is not None else None

    migration_flags = []
    if stage_entry is not None:
        stage_pct = _decimal_or_zero(_value(row, "STAGE_PCT"))
        canonical_pct = Decimal(stage_entry[1])
        if stage_pct != canonical_pct:
            migration_flags.append("stage_pct_mismatch")

    currency = _value(row, "CURR_CD") or "USD"
    exponent = 0 if currency == "JPY" else 2
    amount = _decimal_or_zero(_value(row, "AMT"))
    amount_minor = int(
        (amount * (Decimal(10) ** exponent)).to_integral_value(
            rounding=ROUND_HALF_UP
        )
    )

    lost_reason = _value(row, "LOST_RSN") or None

    return {
        "opportunity_id": _value(row, "OPP_ID"),
        "account_id": _value(row, "ACCT_ID"),
        "name": _value(row, "OPP_NM"),
        "stage": stage,
        "amount_minor": amount_minor,
        "currency": currency,
        "close_date": _date_or_none(_value(row, "CLOSE_DT")),
        "owner_id": _value(row, "OWNER_UID"),
        "team_code": _value(row, "TEAM_CD"),
        "lost_reason": lost_reason,
        "created_date": _date_or_none(_value(row, "CREATE_DT")),
        "updated_date": _date_or_none(_value(row, "UPD_DT")),
        "migration_flags": migration_flags,
    }
